What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    char s[] = "COMPUTER";
    char *p = s + 2;
    printf("%d", (int)(s + 7 - p));
    return 0;
}
```

What does the following C function compute for any 32-bit unsigned integer `n`?
```c
int mystery(unsigned int n) {
    int count = 0;
    while (n) {
        n &= (n - 1);
        count++;
    }
    return count;
}
```

What is the output of the following C program?
```c
#include <stdio.h>
int main() {
    char str[] = "ALGORITHM";
    char *p = str;
    printf("%s", p + p[2] - p[0]);
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    int a[] = {5, 10, 15, 20, 25, 30, 35, 40};
    int *p = a;
    int sum = 0;
    for (int i = 0; i < 4; i++) {
        sum += *p;
        p += (i % 2) + 1;
    }
    printf("%d", sum);
    return 0;
}
```

How many total times is `fib()` called (including the initial call `fib(6)`) by the following C program?
```c
#include <stdio.h>
int count = 0;
int fib(int n) {
    count++;
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}
int main() { fib(6); printf("%d", count); return 0; }
```
